<script setup>
import {ref,computed,watch,nextTick,onMounted,onUnmounted} from 'vue'
import GameHallOfFame from '../components/GameHallOfFame.vue'
import {formatGameTime} from '../lib/gameTime'
import {api} from '../lib/api'
import {cardLevels} from '../data/card-levels'
import {useArcade} from '../stores/arcade'
const arcade=useArcade(),game=ref(null),chosen=ref(1),board=ref(null),columns=ref(4),cardWidth=ref(100),gap=ref(8)
const hallOpen=ref(false),elapsedMs=ref(0);let clockTimer,clockBase=0,clockAnchor=0
function syncClock(result){clearInterval(clockTimer);elapsedMs.value=result.durationMs??result.elapsedMs??0;clockBase=elapsedMs.value;clockAnchor=performance.now();if(!result.done)clockTimer=setInterval(()=>elapsedMs.value=clockBase+performance.now()-clockAnchor,200)}
const FLIP_MS=240,pendingIndex=ref(-1),queuedIndex=ref(-1),closing=ref([]),clearReady=ref(false),knownFaces=ref([]),optimistic=ref([]),retryIndex=ref(-1),retryKey=ref('');let timer,hideTimer,observer,frame,assetsReady,controller
const levels=cardLevels,busy=ref(false),error=ref('');let alive=true,version=0
const faces=[{id:'eevee',name:'이브이'},{id:'jolteon',name:'쥬피썬더'},{id:'vaporeon',name:'샤미드'},{id:'flareon',name:'부스터'},{id:'glaceon',name:'글레이시아'},{id:'sylveon',name:'님피아'},{id:'leafeon',name:'리피아'},{id:'espeon',name:'에브이'},{id:'umbreon',name:'블래키'}]
const config=computed(()=>levels[chosen.value-1]),gridStyle=computed(()=>({'--columns':columns.value,'--card-width':cardWidth.value+'px','--card-gap':gap.value+'px'}))
function fit(){if(!board.value||!game.value)return;const w=Math.max(1,board.value.clientWidth-20),h=Math.max(1,board.value.clientHeight-20),n=game.value.cards.length;gap.value=w<550?6:10;let best=0,bestColumns=4;for(let cols=1;cols<=Math.min(n,12);cols++){const rows=Math.ceil(n/cols),width=Math.min((w-gap.value*(cols-1))/cols,(h-gap.value*(rows-1))/rows*.75,205);if(width>best){best=width;bestColumns=cols}}columns.value=bestColumns;cardWidth.value=Math.max(10,Math.floor(best))}
async function connectBoard(){await nextTick();observer?.disconnect();if(board.value){observer=new ResizeObserver(()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(fit)});observer.observe(board.value);fit()}}
async function start(level=chosen.value){if(busy.value)return;busy.value=true;error.value='';retryIndex.value=-1;retryKey.value='';knownFaces.value=[];optimistic.value=[];clearTimeout(timer);clearTimeout(hideTimer);pendingIndex.value=-1;queuedIndex.value=-1;closing.value=[];clearReady.value=false;const current=++version;try{await preloadFaces();if(!alive||current!==version)return;const result=await api('/cards/start',{method:'POST',body:{level:Number(level),requestKey:crypto.randomUUID()}});if(!alive||current!==version)return;chosen.value=result.level;game.value=result;syncClock(result);connectBoard()}catch(e){if(alive)error.value=e.message}finally{if(alive)busy.value=false}}
function serverVisible(i){return !closing.value.includes(i)&&(game.value.open.includes(i)||game.value.matched.includes(i))}
function visible(i){return serverVisible(i)||optimistic.value.includes(i)}
function preloadFaces(){return assetsReady??=Promise.all(faces.map(face=>new Promise(resolve=>{const img=new Image();img.onload=()=>img.decode?.().catch(()=>{}).finally(resolve)??resolve();img.onerror=resolve;img.src='/images/cards/'+face.id+'.png'})))}
async function flip(i,requestKey){
 const g=game.value;if(!g||g.done||g.open.length===2||closing.value.length||serverVisible(i)||i===pendingIndex.value)return;
 if(busy.value){if(g.open.length===0&&pendingIndex.value>=0&&queuedIndex.value<0){queuedIndex.value=i;if(knownFaces.value[i]!=null)optimistic.value.push(i)}return}
 busy.value=true;pendingIndex.value=i;error.value='';retryIndex.value=-1;if(knownFaces.value[i]!=null&&!optimistic.value.includes(i))optimistic.value.push(i);const current=version,key=requestKey||crypto.randomUUID(),requestController=new AbortController();controller=requestController;const requestTimeout=setTimeout(()=>requestController.abort(),15000);
 try{
  const result=await api('/cards/'+g.id+'/flip',{method:'POST',body:{index:i,requestKey:key},signal:requestController.signal});if(!alive||current!==version)return;
  pendingIndex.value=-1;result.cards.forEach((face,index)=>{if(face!==null)knownFaces.value[index]=face});game.value=result;optimistic.value=optimistic.value.filter(index=>index===queuedIndex.value);syncClock(result);
  if(result.open.length===2){
   optimistic.value=[];queuedIndex.value=-1;
   timer=setTimeout(()=>{if(!alive||current!==version||game.value?.id!==result.id)return;const indices=[...game.value.open];closing.value=indices;
    hideTimer=setTimeout(()=>{if(!alive||current!==version)return;for(const index of indices)game.value.cards[index]=null;game.value.open=[];closing.value=[]},FLIP_MS);
   },FLIP_MS+config.value.delay);
  }
  if(result.done){queuedIndex.value=-1;timer=setTimeout(()=>{if(alive&&current===version)clearReady.value=true},FLIP_MS+120);arcade.refresh({background:true}).catch(()=>{})}
 }catch(e){queuedIndex.value=-1;optimistic.value=[];if(alive&&current===version){retryIndex.value=!e.status||e.status>=500?i:-1;retryKey.value=key;error.value=e.status&&e.status<500?e.message:'연결이 지연됐어요. 다시 연결하면 같은 진행 상태를 확인해요.'}}
 finally{clearTimeout(requestTimeout);if(alive&&current===version){pendingIndex.value=-1;busy.value=false;const queued=queuedIndex.value;queuedIndex.value=-1;if(queued>=0)flip(queued)}}
}
function intro(){if(busy.value)return;version++;clearInterval(clockTimer);clearTimeout(timer);clearTimeout(hideTimer);queuedIndex.value=-1;closing.value=[];observer?.disconnect();game.value=null}
onMounted(()=>{preloadFaces();document.documentElement.classList.add('card-focus-mode');arcade.data.card=null})
onUnmounted(()=>{clearInterval(clockTimer);alive=false;version++;controller?.abort();clearTimeout(timer);clearTimeout(hideTimer);cancelAnimationFrame(frame);observer?.disconnect();document.documentElement.classList.remove('card-focus-mode')})
</script>
<template><section class="card-screen"><GameHallOfFame v-if="hallOpen" game="cards" :level="chosen" @close="hallOpen=false"/><p v-if="error" class="notice" role="alert">{{error}} <button v-if="retryIndex>=0" :disabled="busy" @click="flip(retryIndex,retryKey)">다시 연결</button></p><div v-if="!game" class="card-game-intro"><div class="card-intro-fan" aria-hidden="true"><div class="fan-card fan-back fan-left"><img src="/images/cards/back.png" alt=""/></div><div class="fan-card fan-front"><img src="/images/cards/eevee.png" alt=""/></div><div class="fan-card fan-back fan-right"><img src="/images/cards/back.png" alt=""/></div></div><h1>포켓몬 카드 뒤집기</h1><p>같은 포켓몬 두 장을 찾아요. 레벨을 선택하고 시작하세요.</p><div class="card-intro-levels" aria-label="게임 레벨 선택"><button v-for="level in levels" :key="level.id" :class="['card-level-chip',{selected:chosen===level.id}]" :aria-pressed="chosen===level.id" :disabled="busy" @click="chosen=level.id"><b>LEVEL {{level.id}}</b><span class="card-level-name">{{level.name}}</span><small>{{level.pairs*2}}장 · +{{level.reward}} P</small></button></div><button class="card-start" :disabled="busy" @click="start()">{{busy?'준비 중…':'START'}}</button><button class="light" @click="hallOpen=true">🏆 명예의 전당</button><small class="card-reset-note">다른 화면으로 이동하면 이번 게임은 초기화됩니다.</small></div><template v-else><div class="card-play-top"><div class="card-play-title"><h1>카드 뒤집기</h1><select :disabled="busy" :value="chosen" aria-label="게임 레벨" @change="start(Number($event.target.value))"><option v-for="level in levels" :key="level.id" :value="level.id">LEVEL {{level.id}} · {{level.pairs*2}}장</option></select></div><div class="card-play-stats"><span>시간 <b>{{formatGameTime(elapsedMs)}}</b></span><span>시도 <b>{{game.tries}}</b></span><span>찾은 짝 <b>{{game.matched.length/2}} / {{config.pairs}}</b></span></div><div class="card-play-actions"><button class="light" @click="hallOpen=true">🏆 명예의 전당</button><button :disabled="busy" @click="start()">↻ 재시작</button><button class="light" :disabled="busy" @click="intro">시작 화면</button></div></div><div ref="board" class="card-board-area"><div class="viewport-card-grid" :style="gridStyle"><button v-for="(face,i) in game.cards" :key="i" :class="['memory-card','tcg-card',{revealed:visible(i),matched:game.matched.includes(i),requesting:pendingIndex===i,queued:queuedIndex===i}]" :aria-label="visible(i)?(i+1)+'번 '+faces[face??knownFaces[i]]?.name+' 카드':(i+1)+'번 카드 뒤집기'" :aria-pressed="visible(i)" :disabled="game.done||game.matched.includes(i)||game.open.includes(i)||game.open.length===2||!!closing.length||pendingIndex===i" @click="flip(i)"><span class="tcg-inner"><span class="tcg-side tcg-back"><img src="/images/cards/back.png" alt="" draggable="false"/></span><span class="tcg-side tcg-front"><img v-if="(face??knownFaces[i])!=null" :src="'/images/cards/'+faces[face??knownFaces[i]]?.id+'.png'" alt="" draggable="false"/></span></span><span v-if="game.matched.includes(i)" class="match-check" aria-hidden="true">✓</span></button></div><div v-if="game.done&&clearReady" class="card-clear-overlay"><div class="card-clear-box" role="status"><p class="eyebrow">LEVEL CLEAR!</p><h2>{{chosen===levels.length?'카드 마스터 달성! 🏆':'모든 짝을 찾았어요! 🎉'}}</h2><p>{{game.tries}}번 만에 {{config.pairs}}쌍 완성 · {{formatGameTime(game.durationMs)}}</p><p class="card-reward">🪙 +{{game.reward}}코인 지급 완료!</p><div class="toolbar"><button class="light" @click="hallOpen=true">기록·메달 보기</button><button v-if="chosen<levels.length" @click="start(chosen+1)">다음 레벨 →</button><button :disabled="busy" @click="start()">다시 플레이</button><button class="light" :disabled="busy" @click="intro">시작 화면</button></div></div></div></div><div class="card-play-foot"><span>카드 {{game.cards.length}}장 · 틀린 카드 {{config.delay/1000}}초 공개</span><span>클리어 보상 · {{config.reward}}코인</span></div></template></section></template>

<style scoped>
.tcg-inner{transition:transform 240ms cubic-bezier(.4,0,.2,1)}.tcg-card.requesting:not(.revealed) .tcg-back{outline:3px solid var(--rpg-mid);outline-offset:2px}.tcg-card.queued{outline:2px solid var(--rpg-mid);outline-offset:3px}.tcg-card.memory-card:disabled{filter:none;opacity:1}.tcg-card.memory-card:hover{transform:none}@media(prefers-reduced-motion:reduce){.tcg-inner{transition-duration:0ms}}

.card-intro-levels{grid-template-columns:repeat(4,minmax(0,1fr));width:min(900px,100%)}@media(max-width:600px){.card-intro-levels{gap:7px}.card-level-chip{min-width:0;padding:8px 3px}.card-intro-fan{height:125px}.fan-card{width:80px}.card-game-intro{gap:9px}}
</style>
